        unsigned long long prev_one = dp_lat[s_i - 1];
        unsigned long long prev_two = dp_lat[s_i - 2];
        dp_lat[s_i] = prev_one + prev_two;
    }
    if (rem_cells >= 0) {
        lat_total = dp_lat[rem_cells] + base_ways;
    }
    std::cout << lat_total << std::endl;
    return 0;
}

